<?php
 namespace App; use App\Jobs\OrderSms; use App\Library\LogHelper; use App\Mail\OrderShipped; use App\Model_ as Model; use Illuminate\Support\Facades\Mail; use Illuminate\Support\Facades\Log as LogWriter; class Order extends Model { protected $guarded = []; const STATUS_UNPAY = 0; const STATUS_PAID = 1; const STATUS_SUCCESS = 2; const STATUS_FROZEN = 3; const STATUS_REFUND = 4; const STATUS = [ 0 => '未支付', 1 => '未发货', 2 => '已发货', 3 => '已冻结', 4 => '已退款', ]; const SEND_STATUS_UN = 0; const SEND_STATUS_EMAIL_SUCCESS = 1; const SEND_STATUS_EMAIL_FAILED = 2; const SEND_STATUS_MOBILE_SUCCESS = 3; const SEND_STATUS_MOBILE_FAILED = 4; const SEND_STATUS_CARD_UN = 100; const SEND_STATUS_CARD_PROCESSING = 101; const SEND_STATUS_CARD_SUCCESS = 102; const SEND_STATUS_CARD_FAILED = 103; protected $casts = [ 'api_info' => 'array', ]; public static function unique_no() { $order_no = date('YmdHis') . str_random(5); while (\App\Order::where('order_no', $order_no)->exists()) { $order_no = date('YmdHis') . str_random(5); } return $order_no; } function user() { return $this->belongsTo(User::class); } function product() { return $this->belongsTo(Product::class); } function pay() { return $this->belongsTo(Pay::class); } function cards() { $builder = $this->belongsToMany(Card::class); return $builder->withTrashed(); } function card_orders() { return $this->hasMany(CardOrder::class); } function fundRecord() { return $this->hasMany(FundRecord::class); } function getCardsArray() { $cards = []; $this->cards->each(function ($card) use (&$cards) { $cards[] = $card->card; }); return $cards; } function getSendMessage() { if (count($this->cards)) { if (count($this->cards) == $this->count) { $card_msg = '订单#' . $this->order_no . '&nbsp;已支付，您购买的内容如下：'; } else { if ( $this->cards[0]->type === \App\Card::TYPE_REPEAT || @$this->product->delivery === \App\Product::DELIVERY_MANUAL ) { $card_msg = '订单#' . $this->order_no . '&nbsp;已支付，您购买的内容如下：'; } else { $card_msg = '订单#' . $this->order_no . '&nbsp;已支付，目前库存不足，您还有' . ($this->count - count($this->cards)) . '件未发货，请联系商家客服发货，'; $card_msg .= '商家客服QQ：<a href="http://wpa.qq.com/msgrd?v=3&uin=' . $this->user->qq . '&site=qq&menu=yes" target="_blank">' . $this->user->qq . '</a><br>'; $card_msg .= '已发货商品见下方：'; } } } else { $card_msg = '订单#' . $this->order_no . '&nbsp;已支付，目前库存不足，您购买的' . ($this->count - count($this->cards)) . '件未发货，请联系商家客服发货<br>'; $card_msg .= '商家客服QQ：<a href="http://wpa.qq.com/msgrd?v=3&uin=' . $this->user->qq . '&site=qq&menu=yes" target="_blank">' . $this->user->qq . '</a>'; } return $card_msg; } function sendEmail($mail = false) { if ($mail === false) { $mail = @json_decode($this->contact_ext)['_mail']; } if (!$mail || !@filter_var($mail, FILTER_VALIDATE_EMAIL)) { return; } $cards = $this->getCardsArray(); try { Mail::to($mail)->Queue(new OrderShipped($this, $this->getSendMessage(), join('<br>', $cards))); $this->send_status = \App\Order::SEND_STATUS_EMAIL_SUCCESS; $this->saveOrFail(); } catch (\Throwable $e) { $this->send_status = \App\Order::SEND_STATUS_EMAIL_FAILED; $this->saveOrFail(); LogHelper::setLogFile('mail'); LogWriter::error('Order.sendEmail error', [ 'order_no' => $this->order_no, 'email' => $mail, 'cards' => $cards, 'exception' => $e->getMessage() ]); LogHelper::setLogFile('card'); } } function sendSms($mobile = false) { if ($mobile === false) { $mobile = @json_decode($this->contact_ext)['_mobile']; } if (!$mobile || strlen($mobile) !== 11) { return; } OrderSms::dispatch($mobile, $this); } } 